import{_ as s,a0 as n,w as p,s as r,ao as d,I as t,x as o,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Below：一個時間旅行的資源監控器 | LCTT x X-CMD","titleTemplate":false,"description":"Below：一個時間旅行的資源監控器 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Below：一個時間旅行的資源監控器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Below：一個時間旅行的資源監控器 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20210818 below- a time traveling resource monitor","title":"Below：一個時間旅行的資源監控器","tag":"202110","desc":""},"relativePath":"202110/20210818 below- a time traveling resource monitor.md","filePath":"[post].md"}'),u={name:"202110/20210818 below- a time traveling resource monitor.md"};function b(g,e,m,f,w,k){const l=n("Link");return p(),r("div",null,[e[38]||(e[38]=d('<h1 id="below-一個時間旅行的資源監控器" tabindex="-1">Below：一個時間旅行的資源監控器 <a class="header-anchor" href="#below-一個時間旅行的資源監控器" aria-label="Permalink to “Below：一個時間旅行的資源監控器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202110/06/093522hdsb82nm1cb4b4b6.jpg" alt=""></p><p>在這篇文章中，我們將介紹 <code>below</code>：一個用於現代 Linux 系統的 Apache 2.0 許可的資源監視器。<code>below</code> 可以讓你重放以前記錄的數據。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/08/below_resource_monitor-816x345.jpg" alt=""></p><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h3><p>內核的主要職責之一是調度對資源的訪問。有時這可能意味着分配物理內存，使多個進程可以共享同一主機。其他時候，它可能意味着確保 CPU 時間的公平分配。在這些場景裏，內核提供了機制，而將策略留給了“別人”。近來，這個“別人”通常是 systemd 或 dockerd 這樣的運行時。運行時接受來自調度器或最終用户的輸入（類似於運行什麼和如何運行）並在內核上轉動正確的旋鈕和拉動正確的槓桿，從而使工作負載能夠<em>好好</em>工作。</p><p>在一個完美的世界裏，故事就到此結束了。然而，現實情況是，資源管理是一個複雜的、相當不透明的技術混合體，在幾十年裏計算技術不斷發展。儘管其中一些技術有各種缺陷和死角，但最終的結果是，容器運作得比較好。雖然用户通常不需要關心這些細節，但對於基礎設施運營商來説，對他們的技術架構擁有可見性是至關重要的。可見性和可調試性對於檢測和調查錯誤的配置、問題和系統性故障至關重要。</p><p>讓事情變得更加複雜的是，資源中斷往往難以重現。經常需要花費數週時間等待一個問題重新出現，以便調查其根本原因。規模的擴大進一步加劇了這個問題：我們不能在<em>每台</em>主機上運行一個自定義腳本，希望在錯誤再次發生時記錄下關鍵狀態的片段。因此，需要更復雜的工具。這就出現了 <code>below</code>。</p><h3 id="動機" tabindex="-1">動機 <a class="header-anchor" href="#動機" aria-label="Permalink to “動機”">​</a></h3>',9)),t("p",null,[e[1]||(e[1]=o("歷史上，Facebook 一直是 ",-1)),a(l,{href:"https://www.atoptool.nl/"},{default:i(()=>[...e[0]||(e[0]=[o("atop",-1)])]),_:1}),e[2]||(e[2]=o(" 的忠實用户。",-1)),e[3]||(e[3]=t("code",null,"atop",-1)),e[4]||(e[4]=o(" 是一個用於 Linux 的性能監視器，能夠報告所有進程的活動以及各種系統級活動。與 ",-1)),e[5]||(e[5]=t("code",null,"htop",-1)),e[6]||(e[6]=o(" 等工具相比，",-1)),e[7]||(e[7]=t("code",null,"atop",-1)),e[8]||(e[8]=o(" 最引人注目的功能之一是能夠作為一個守護程序記錄歷史數據。這聽起來是一個簡單的功能，但在實踐中，這使得調試無數的生產問題成為可能。有了足夠長的數據保留，就有可能在時間上回溯，查看在問題或故障發生之前、期間和之後的主機狀態。",-1))]),t("p",null,[e[11]||(e[11]=o("不幸的是，隨着時間的推移，人們發現",-1)),e[12]||(e[12]=t("code",null,"atop",-1)),e[13]||(e[13]=o(" 有某些不足之處。首先，",-1)),t("ruby",null,[a(l,{href:"https://en.wikipedia.org/wiki/Cgroups"},{default:i(()=>[...e[9]||(e[9]=[o("控制組",-1)])]),_:1}),e[10]||(e[10]=t("rt",null,"cgroup",-1))]),e[14]||(e[14]=o(" 已經成為控制和監視 Linux 機器上資源的實際方式。",-1)),e[15]||(e[15]=t("code",null,"atop",-1)),e[16]||(e[16]=o(" 仍然缺乏對這一基本構建模組的支持。第二，",-1)),e[17]||(e[17]=t("code",null,"atop",-1)),e[18]||(e[18]=o(" 用自定義的 delta 壓縮方法在磁盤上存儲數據。這在正常情況下運行良好，但在沉重的資源壓力下，主機很可能會丟失數據點。由於使用了 delta 壓縮，在數據最重要的時間段內，數據可能會大面積丟失。第三，用户體驗有一個陡峭的學習曲線。我們經常聽到 ",-1)),e[19]||(e[19]=t("code",null,"atop",-1)),e[20]||(e[20]=o(" 的資深用户説，他們喜歡密集的佈局和眾多的鍵盤綁定。然而，這也是一把雙刃劍。當一個剛進入這個領域的人想要調試一個生產問題時，他們現在要同時解決兩個問題：手頭的問題和如何使用 ",-1)),e[21]||(e[21]=t("code",null,"atop",-1)),e[22]||(e[22]=o("。",-1))]),e[39]||(e[39]=d('<p><code>below</code> 是由 Facebook 的資源控制團隊為其設計和開發的，並得到了 <code>atop</code> 生產環境用户的支持。顧名思義，資源控制團隊負責的是規模化的資源管理。該團隊由內核開發人員、容器運行時開發人員和硬件人員組成。認識到下一代系統監控器的機會，我們在設計 <code>below</code> 時考慮到以下幾點：</p><ul><li>易用性：<code>below</code> 必須既能為新用户提供直觀的體驗，又能為日常用户提供強大的功能。 *有意義的統計數據：<code>below</code> 顯示準確和有用的統計數據。即便可以，但我們儘量避免收集和傾倒統計數字。</li><li>靈活性：當默認設置不合適時，我們允許用户自定義他們的體驗。例如包括可配置的鍵綁定、可配置的默認視圖，以及腳本界面（默認為終端用户接口）。</li></ul><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>安裝該軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install -y below</span></span></code></pre></div><p>打開記錄守護進程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl enable --now below</span></span></code></pre></div><h3 id="快速介紹" tabindex="-1">快速介紹 <a class="header-anchor" href="#快速介紹" aria-label="Permalink to “快速介紹”">​</a></h3><p><code>below</code> 最常用的模式是重放模式。顧名思義，重放模式是重放以前記錄的數據。假設你已經啓動了記錄守護程序，那麼通過運行以下程序啓動一個會話：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ below replay --time &quot;5 minutes ago&quot;</span></span></code></pre></div><p>然後你會看到控制組視圖：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/08/image-1024x800.png" alt=""></p><p>如果你不知道該怎麼操作，或者忘記了一個鍵位，按 <code>?</code> 可以進入幫助菜單。</p><p>屏幕的最上方是狀態欄。狀態欄顯示關於當前樣本的信息。你可以通過按 <code>t</code> 和 <code>T</code> 分別向前和向後移動樣本。中間的部分是系統概覽。系統概覽包含了關於整個系統的統計數據，一般來説，這些數據總是很有用的。第三部分也是最下面的部分是多用途視圖。上面的圖片顯示了控制組視圖。此外，還有進程和系統視圖，分別通過按 <code>p</code> 和<code> s</code> 來訪問。</p><p>按 <code>↑</code> 和 <code>↓</code> 來移動列表選擇。按回車鍵來摺疊和展開控制組。假設你發現了一個感興趣的控制組，你想看看它裏面有哪些進程在運行。要放大進程視圖，選擇控制組並按 <code>z</code>：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/08/image-1-1024x800.png" alt=""></p><p>再按 <code>z</code> 返回到控制組視圖。這個視圖有時會有點長。如果你對你要找的東西有一個模糊的概念，你可以通過按 <code>/</code> 並輸入一個過濾器來過濾控制組名稱。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/08/image-2-1024x800.png" alt=""></p><p>在這一點上，你可能已經注意到了一個我們還沒有探索過的標籤系統。要在標籤中向前和向後循環，可以分別按 <code>Tab</code> 和 <code>Shift</code> + <code>Tab</code>。我們把這個問題留給讀者去做練習。</p><h3 id="其他功能" tabindex="-1">其他功能 <a class="header-anchor" href="#其他功能" aria-label="Permalink to “其他功能”">​</a></h3><p>在底層，<code>below</code> 有一個強大的設計和架構。Facebook 正在不斷升級到更新的內核，所以我們從不假設數據源是可用的。這種默契的假設使得內核和 <code>below </code>版本之間能夠完全向前和向後兼容。此外，每個數據點都用 zstd 壓縮並完整地存儲。這解決了我們看到的 <code>atop</code> 在大規模時的 delta 壓縮問題。根據我們的測試，我們的每個樣本壓縮可以達到平均 5 倍的壓縮率。</p><p><code>below</code> 也使用 [eBPF][8] 來收集關於短暫進程（生存時間短於數據收集間隔的進程）的信息。相比之下，<code>atop</code> 使用 BSD 進程核算來實現這一功能，這是一個已知緩慢且容易發生優先級轉換的內核接口。</p><p>對於用户來説，<code>below</code> 還支持實時模式和一個轉儲接口。實時模式將記錄守護程序和 TUI 會話合併到一個進程中。這對於瀏覽系統狀態是很方便的，不需要為數據存儲投入長期運行的守護程序或磁盤空間。轉儲接口是一個可編寫腳本的接口，用於所有的 <code>below</code> 數據存儲。轉儲既強大又靈活，詳細的數據以 CSV、JSON 和人類可讀格式提供。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p><code>below</code> 是一個 Apache 2.0 許可的開源項目，我們（<code>below</code> 的開發者）認為它比資源監控領域的現有工具具有引人注目的優勢。我們已經花了大量的精力來準備 <code>below</code>，以提供開源使用，所以我們希望讀者和社區有機會嘗試 <code>below</code>，並報告錯誤和功能要求。</p><hr>',26)),t("p",null,[e[24]||(e[24]=o("via: ",-1)),a(l,{href:"https://fedoramagazine.org/below-a-time-traveling-resource-monitor/"},{default:i(()=>[...e[23]||(e[23]=[o("https://fedoramagazine.org/below-a-time-traveling-resource-monitor/",-1)])]),_:1})]),t("p",null,[e[29]||(e[29]=o("作者：",-1)),a(l,{href:"https://fedoramagazine.org/author/dxuu/"},{default:i(()=>[...e[25]||(e[25]=[o("Daniel Xu",-1)])]),_:1}),e[30]||(e[30]=o(" 選題：",-1)),a(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[26]||(e[26]=[o("lujun9972",-1)])]),_:1}),e[31]||(e[31]=o(" 譯者：",-1)),a(l,{href:"https://github.com/wxy"},{default:i(()=>[...e[27]||(e[27]=[o("wxy",-1)])]),_:1}),e[32]||(e[32]=o(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:i(()=>[...e[28]||(e[28]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[35]||(e[35]=o("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[33]||(e[33]=[o("LCTT",-1)])]),_:1}),e[36]||(e[36]=o(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:i(()=>[...e[34]||(e[34]=[o("Linux中國",-1)])]),_:1}),e[37]||(e[37]=o(" 榮譽推出",-1))])])}const C=s(u,[["render",b]]);export{T as __pageData,C as default};
